// HMAC-SHA1 (RFC 2104) — pure JS, no dependencies.
// Block size for SHA-1 is 64 bytes; ipad = 0x36, opad = 0x5c.

import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64;
const IPAD = 0x36;
const OPAD = 0x5c;

export function hmacSha1(key, message) {
  // Keys longer than the block size are hashed first.
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha1(k);
  }

  // Pad the key with zeros up to the block size.
  const padded = new Uint8Array(BLOCK_SIZE);
  padded.set(k);

  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    innerPad[i] = padded[i] ^ IPAD;
    outerPad[i] = padded[i] ^ OPAD;
  }

  // inner = SHA-1(innerPad || message)
  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(innerPad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha1(inner);

  // HMAC = SHA-1(outerPad || innerHash)
  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(outerPad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha1(outer);
}

