// Entry point — pure Node.js ES Module port of the Python pbkdf2 script.
// Usage: node test7.mjs --a <passphrase> --b <salt1> --c <salt2>
// Derives two 24-byte keys (PBKDF2-HMAC-SHA1, 1000 iterations) and prints
// each key's lowercase hex on its own line.

import { parseArgs } from './cli/args.mjs';
import { PBKDF2 } from './pbkdf2/pbkdf2.mjs';

const args = parseArgs(process.argv.slice(2));

// key1: passphrase = args.a, salt = args.b (default 1000 iterations)
const key1 = new PBKDF2(args.a, args.b).read(24);
// key2: passphrase = args.a, salt = args.c
const key2 = new PBKDF2(args.a, args.c).read(24);

console.log(Buffer.from(key1).toString('hex'));
console.log(Buffer.from(key2).toString('hex'));

