// Command-line argument parser for test7.
// Manual, argparse-like parsing of `--a`, `--b`, `--c` (required string options),
// supporting both `--a value` and `--a=value` forms.
// On any usage error: message to stderr, exit code 2.

const OPTION_NAMES = ["--a", "--b", "--c"];

const PROG = "test7.mjs";

function usage() {
  return `usage: ${PROG} [-h] --a A --b B --c C`;
}

function fail(message) {
  process.stderr.write(`${usage()}\n${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  const values = { "--a": null, "--b": null, "--c": null };

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === "-h" || token === "--help") {
      process.stdout.write(
        `${usage()}\n\noptions:\n` +
          `  -h, --help  show this help message and exit\n` +
          `  --a A       passphrase (required)\n` +
          `  --b B       first salt (required)\n` +
          `  --c C       second salt (required)\n`
      );
      process.exit(0);
    }

    let name = token;
    let inlineValue = null;

    if (token.startsWith("--")) {
      const eq = token.indexOf("=");
      if (eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
    }

    if (!OPTION_NAMES.includes(name)) {
      fail(`unrecognized arguments: ${token}`);
    }

    if (values[name] !== null) {
      fail(`argument ${name}: specified more than once`);
    }

    let value;
    if (inlineValue !== null) {
      // --a=value form (empty string after '=' is a valid value)
      value = inlineValue;
    } else {
      // --a value form
      if (i + 1 >= argv.length || argv[i + 1].startsWith("--")) {
        fail(`argument ${name}: expected one argument`);
      }
      value = argv[i + 1];
      i += 1;
    }

    values[name] = value;
    i += 1;
  }

  const missing = OPTION_NAMES.filter((n) => values[n] === null);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(", ")}`);
  }

  return { a: values["--a"], b: values["--b"], c: values["--c"] };
}

