// Pure-JS SHA-1 implementation (FIPS 180-1), no dependencies.
// Operates on Uint8Array input, returns a 20-byte Uint8Array digest.

function rotl32(x, n) {
  return ((x << n) | (x >>> (32 - n))) | 0;
}

export function sha1(data) {
  if (!(data instanceof Uint8Array)) {
    throw new TypeError('sha1: data must be a Uint8Array');
  }

  // Padding: append 0x80, then zeros, then 64-bit big-endian bit length,
  // so the total length is a multiple of 64 bytes.
  const bitLenHi = Math.floor(data.length / 0x20000000); // floor(len * 8 / 2^32)
  const bitLenLo = (data.length * 8) >>> 0;
  const paddedLen = (((data.length + 8) >> 6) + 1) << 6;
  const msg = new Uint8Array(paddedLen);
  msg.set(data);
  msg[data.length] = 0x80;
  const dv = new DataView(msg.buffer);
  dv.setUint32(paddedLen - 8, bitLenHi, false);
  dv.setUint32(paddedLen - 4, bitLenLo, false);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w = new Int32Array(80);

  for (let block = 0; block < paddedLen; block += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = dv.getUint32(block + t * 4, false) | 0;
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl32(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f, k;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const tmp = (rotl32(a, 5) + f + e + k + w[t]) | 0;
      e = d;
      d = c;
      c = rotl32(b, 30);
      b = a;
      a = tmp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const out = new Uint8Array(20);
  const odv = new DataView(out.buffer);
  odv.setUint32(0, h0 >>> 0, false);
  odv.setUint32(4, h1 >>> 0, false);
  odv.setUint32(8, h2 >>> 0, false);
  odv.setUint32(12, h3 >>> 0, false);
  odv.setUint32(16, h4 >>> 0, false);
  return out;
}

const HEX = '0123456789abcdef';

export function sha1Hex(data) {
  const digest = sha1(data);
  let s = '';
  for (let i = 0; i < digest.length; i++) {
    s += HEX[digest[i] >> 4] + HEX[digest[i] & 0x0f];
  }
  return s;
}

