// RFC 2898 PBKDF2 with HMAC-SHA1, pure JS (no dependencies).
import { hmacSha1 } from '../hash/hmac.mjs';

const encoder = new TextEncoder();

// Derive dkLen bytes of key material from UTF-8 strings per RFC 2898 §5.2.
export function pbkdf2Sha1(password, salt, iterations, dkLen) {
  const key = encoder.encode(password);
  const saltBytes = encoder.encode(salt);
  const hLen = 20; // SHA-1 digest size
  const blockCount = Math.ceil(dkLen / hLen);
  const derived = new Uint8Array(blockCount * hLen);
  // salt || INT_32_BE(i), reused per block with the counter written at the end
  const blockInput = new Uint8Array(saltBytes.length + 4);
  blockInput.set(saltBytes);

  for (let i = 1; i <= blockCount; i++) {
    blockInput[saltBytes.length] = (i >>> 24) & 0xff;
    blockInput[saltBytes.length + 1] = (i >>> 16) & 0xff;
    blockInput[saltBytes.length + 2] = (i >>> 8) & 0xff;
    blockInput[saltBytes.length + 3] = i & 0xff;

    let u = hmacSha1(key, blockInput); // U_1
    const t = new Uint8Array(u); // T_i starts as U_1
    for (let j = 2; j <= iterations; j++) {
      u = hmacSha1(key, u); // U_j = PRF(password, U_{j-1})
      for (let k = 0; k < hLen; k++) {
        t[k] ^= u[k];
      }
    }
    derived.set(t, (i - 1) * hLen);
  }

  return derived.slice(0, dkLen);
}

// Streaming interface mimicking Python's pbkdf2.PBKDF2: successive read(len)
// calls advance through the derived keystream.
export class PBKDF2 {
  constructor(passphrase, salt, iterations = 1000) {
    this.passphrase = passphrase;
    this.salt = salt;
    this.iterations = iterations;
    this.buffer = new Uint8Array(0); // derived-but-unread bytes
    this.totalRead = 0; // bytes consumed so far
  }

  read(len) {
    if (this.buffer.length < len) {
      // Not enough buffered bytes: re-derive the keystream, rounded up to a
      // whole 20-byte block past what this read needs, and keep only the
      // unconsumed tail (bytes before totalRead were already handed out).
      const needed = this.totalRead + len;
      const target = needed + (20 - (needed % 20)) % 20 + 20;
      const full = pbkdf2Sha1(this.passphrase, this.salt, this.iterations, target);
      this.buffer = full.slice(this.totalRead);
    }
    const out = this.buffer.slice(0, len);
    this.buffer = this.buffer.slice(len);
    this.totalRead += len;
    return out;
  }
}
